package apidocs

func (d *document) attendance() {
	d.op("Attendance", "POST", "/api/v1/scanner-devices", "Register scanner and issue credential", admin, "IssuedScannerCredential", 201).body("RegisterScanner").fail(409, "Duplicate scanner name.").note("Credential is returned ONCE. Save on the scanner, never in source control. New scanner direction must be configured before scans.")
	d.op("Attendance", "GET", "/api/v1/scanner-devices", "List scanner metadata", admin, "ScannerPage", 200).paging(1000000).note("Listings never return credential material.")
	d.op("Attendance", "POST", "/api/v1/scanner-devices/{deviceID}/rotate-credential", "Rotate scanner credential", admin, "IssuedScannerCredential", 200).note("Empty body. New credential returned once; old credential immediately stops authenticating.")
	d.op("Attendance", "POST", "/api/v1/scanner-devices/{deviceID}/deactivate", "Deactivate scanner", admin, "ScannerDevice", 200).note("Empty body. Existing credential cannot authenticate after deactivation.")
	d.op("Attendance", "PUT", "/api/v1/scanner-devices/{deviceID}/direction", "Configure scanner IN or OUT direction", admin, "ScannerDevice", 200).body("SetScannerDirection").note("Direction is configured server-side, never chosen in the scan body.")
	d.op("Attendance", "GET", "/api/v1/device/check", "Check active scanner credentials", "scanner", "ScannerCheck", 200).scanner()
	d.op("Attendance", "POST", "/api/v1/device/scans", "Record an explicit Student QR scan", "scanner", "ScanEvent", 200).scanner().body("RecordScan").fail(413, "").fail(409, "direction_not_configured, event_conflict or another scan state conflict.").note("Use a new event_id for each physical scan and retain it with identical QR on retry. Device direction determines movement; no toggle semantics. Server timestamps events. Duplicate-direction/cooldown events may be suppressed; only recorded movements affect presence. Restricted movement without permission still records physical attendance and creates an incident. Approved matching late access is consumed once within the inclusive +/-30-minute expected_at window. Response outcome/access_result must be inspected.")
	d.op("Attendance", "GET", "/api/v1/attendance/presence", "Read one Student's scanned presence", staffReaders, "Presence", 200).param("query", "student_id", "Required Student profile UUID.", uuidQuery(), true)
	d.op("Attendance", "GET", "/api/v1/attendance/events", "List one Student's scan events", staffReaders, "EventPage", 200).param("query", "student_id", "Required Student profile UUID.", uuidQuery(), true).paging(1000000).note("Includes recorded and suppressed processing outcomes; use Student-owned history for the mobile movement timeline.")
	d.op("Attendance", "GET", "/api/v1/attendance/students", "List Student presence dashboard", staffReaders, "PresencePage", 200).paging(1000000).query("q", object{"type": "string", "maxLength": 200}, "Name/index search.").query("status", enumeration("IN", "OUT", "UNKNOWN"), "Current presence state.")
	d.op("Attendance", "GET", "/api/v1/attendance/summary", "Get presence counts", staffReaders, "PresenceSummary", 200).query("q", object{"type": "string", "maxLength": 200}, "Name/index search; other filters are not accepted.").note("Counts IN + OUT + UNKNOWN = total for eligible Students matching the search.")
	d.op("Attendance", "GET", "/api/v1/attendance/incidents", "List unapproved restricted-movement incidents", staffReaders, "IncidentPage", 200).paging(1000000).query("student_id", uuidQuery(), "Student filter.").query("direction", enumeration("IN", "OUT"), "Movement direction.").query("incident_type", enumeration("early_exit", "late_exit", "late_entry"), "Incident type. Late exit is OUT at/after the closing time; pre-opening OUT is early_exit.")
	d.op("Attendance", "GET", "/api/v1/attendance/incidents/{incidentID}", "Get attendance incident", staffReaders, "Incident", 200)
	d.op("Attendance", "POST", "/api/v1/attendance/realtime/session", "Grant a short-lived RTDB read session", staffReaders, "RealtimeSession", 200).note("Empty body. Requires enabled RTDB configuration;503 when unavailable. Returns the allowed database URL/path and renewal interval, not a database secret. Connect Firebase RTDB using the same authenticated identity; permissions revoke on role/account changes.")
	d.op("Attendance", "GET", "/api/v1/attendance/realtime/status", "Get RTDB publication status", staffReaders, "PublicationStatus", 200).note("Operational metadata only; no listener grant or Student personal details.")
	d.op("Attendance", "GET", "/api/v1/me/attendance/events", "List own recorded attendance movements", student, "StudentMovementPage", 200).paging(1000000).query("from", object{"type": "string", "format": "date"}, "Optional local first date; requires to, maximum366 inclusive days.").query("to", object{"type": "string", "format": "date"}, "Optional local last date; requires from. Asia/Colombo by default.").query("direction", enumeration("IN", "OUT"), "Movement direction.").note("Only recorded movements; no suppressed scans or scanner credentials. Owned profile is derived from account. student_id/user_id selectors are rejected. movement_id is the stable combined list identity. Reads never change presence.")
}
